// Move data for battles. The JSON files are generated by
// app/scripts/002buildMovesData.js - re-run that script to change them.
import movesData from '../data/moves.json';
import pokemonMovesData from '../data/pokemonMoves.json';
import { PokemonType } from './pokemonTypeEffectiveness';

// Stats a move can raise or lower for the rest of a battle.
export type MoveStat = 'attack' | 'defense' | 'speed' | 'accuracy' | 'evasion';

export interface IMoveEffect {
  target: 'self' | 'opponent';
  changes: { stat: MoveStat; stages: number }[];
}

export interface IMove {
  name: string;
  type: PokemonType;
  category: 'damage' | 'status';
  power: number; // 0 for stat-changing moves
  accuracy: number | null; // percent; null means it never misses
  effect?: IMoveEffect;
  description?: string;
}

const moves = movesData as unknown as Record<string, IMove>;
const pokemonMoves = pokemonMovesData as unknown as Record<
  string,
  { name: string; base: string[]; learnable: string[] }
>;

// Used when a Pokemon has no usable attack, or a move name isn't recognised.
export const FALLBACK_MOVE_NAME = 'struggle';
// Used when a Pokemon is created with no move list at all.
export const DEFAULT_MOVE_NAME = 'tackle';

export function isKnownMove(name: string): boolean {
  return name.toLowerCase() in moves;
}

const warnedUnknownMoves = new Set<string>();

/**
 * Look up a move by name. An unrecognised name is reported once in the
 * console and behaves like Struggle, so a battle never breaks on bad data.
 */
export function getMove(name: string): IMove {
  const key = name.toLowerCase();
  const move = moves[key];
  if (move) return move;

  if (!warnedUnknownMoves.has(key)) {
    warnedUnknownMoves.add(key);
    console.error(
      `Move "${name}" is not in app/data/moves.json. It will behave like ${FALLBACK_MOVE_NAME}.`
    );
  }
  return { ...moves[FALLBACK_MOVE_NAME], name: key };
}

/** The four (or fewer) moves a Pokemon starts with. */
export function getBaseMoves(pokedexNumber: number): string[] {
  return pokemonMoves[pokedexNumber]?.base ?? [];
}

/** Every move a Pokemon is able to learn (for training later on). */
export function getLearnableMoves(pokedexNumber: number): string[] {
  return pokemonMoves[pokedexNumber]?.learnable ?? [];
}

/**
 * The moves a Pokemon fights with: its own saved moves if it has any valid
 * ones (for moves learned later), otherwise its base moves.
 */
export function resolveMoves(
  pokedexNumber: number,
  savedMoves?: string[] | null
): string[] {
  const saved = (savedMoves ?? []).filter(isKnownMove).slice(0, 4);
  if (saved.length > 0) return saved;

  const base = getBaseMoves(pokedexNumber);
  return base.length > 0 ? base : [FALLBACK_MOVE_NAME];
}

/** "thunder-shock" -> "Thunder Shock" */
export function formatMoveName(name: string): string {
  return name
    .split('-')
    .map((word) => word.charAt(0).toUpperCase() + word.slice(1))
    .join(' ');
}

export const MOVE_STAT_LABELS: Record<MoveStat, string> = {
  attack: 'Attack',
  defense: 'Defense',
  speed: 'Speed',
  accuracy: 'accuracy',
  evasion: 'evasion',
};

export const MOVE_STAT_SHORT_LABELS: Record<MoveStat, string> = {
  attack: 'ATK',
  defense: 'DEF',
  speed: 'SPD',
  accuracy: 'ACC',
  evasion: 'EVA',
};
